    fontSize: 13,
    color: colors.textSecondary,
    marginTop: 2,
  },
  activeGenre: {
    color: colors.primary,
    fontWeight: '600',
  },
  aiButton: {
    backgroundColor: colors.primary,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: 12,
    borderRadius: 24,
    marginBottom: 12,
  },
  aiButtonDisabled: {
    opacity: 0.6,
  },
  aiButtonText: {
    color: '#000',
    fontSize: 13,
    fontWeight: '700',
  },
  statusText: {
    color: colors.primary,
    textAlign: 'center',
    fontSize: 12,
    marginBottom: 8,
  },
  slidersRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    height: 180,
    marginVertical: 12,
    paddingHorizontal: 4,
  },
  sliderCol: {
    alignItems: 'center',
    justifyContent: 'space-between',
    width: 48,
  },
  valText: {
    color: colors.textSecondary,
    fontSize: 11,
    fontWeight: '600',
  },
  verticalSliderWrapper: {
    height: 120,
    width: 40,
    justifyContent: 'center',
    alignItems: 'center',
  },
  verticalSlider: {
    width: 120,
    height: 40,
    transform: [{ rotate: '-90deg' }],
  },
  freqText: {
    color: colors.text,
    fontSize: 11,
    fontWeight: '500',
  },
  presetsHeader: {
    fontSize: 11,
    fontWeight: '700',
    color: colors.textSecondary,
    letterSpacing: 1,
    marginTop: 12,
    marginBottom: 8,
  },
  presetsRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
    marginBottom: 16,
  },
  presetChip: {
    backgroundColor: 'rgba(255, 255, 255, 0.08)',
    paddingHorizontal: 14,
    paddingVertical: 8,
    borderRadius: 16,
  },
  presetChipActive: {
    backgroundColor: colors.primary,
  },
  presetText: {
    color: colors.text,
    fontSize: 12,
