const SUGGESTIONS = [
  'Late night drive Hindi & English lo-fi',
  'High energy gym phonk & bass boost',
  'Rainy day acoustic & sad Bollywood',
  'Instagram reels trending & viral hits',
  '90s Bollywood romantic nostalgia',
  'Upbeat energetic pop & party mix',
