          {item.name}
        </Text>
        <Text style={styles.artistRole}>Artist</Text>
      </TouchableOpacity>
    );
  };

  useEffect(() => {
    loadData();
  }, [loadData]);









  return (
    <SafeAreaView style={styles.safeArea}>
      {/* Top Header */}
      <View style={styles.header}>
        <Text style={styles.greeting}>{getGreeting()}</Text>
        <View style={styles.headerActions}>
