import React, { useState, useEffect, useCallback } from 'react';
import {
  View,
  Text,
  FlatList,
  Image,
  TouchableOpacity,
  StyleSheet,
  SafeAreaView,
  ActivityIndicator,
  Modal,
  TextInput,
  Alert,
} from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { Ionicons } from '@expo/vector-icons';
import { colors } from '../../theme/colors';
import { useAuth } from '../../context/AuthContext';
import { usePlayer } from '../../context/PlayerContext';
import { playlistApi } from '../../api/playlistApi';
import { musicApi } from '../../api/musicApi';
import { SongItem } from '../../components/SongItem';

export const LibraryScreen = ({ navigation }) => {
  const { user } = useAuth();
  const { playSong } = usePlayer();

  const [activeTab, setActiveTab] = useState('playlists'); // 'playlists' | 'recent' | 'artists'
  const [playlists, setPlaylists] = useState([]);
  const [recentSongs, setRecentSongs] = useState([]);
  const [followingArtists, setFollowingArtists] = useState([]);
  const [loading, setLoading] = useState(true);

  // Create playlist modal
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [creating, setCreating] = useState(false);

  const loadData = useCallback(async () => {
    try {
      // 1. Playlists
      const plData = await playlistApi.getLibrary();
      setPlaylists(plData.array || []);

      // 2. Recently Played
      const recData = await musicApi.getRecentlyPlayed();
      setRecentSongs(recData.arr || []);

      // 3. Artists
      if (user?.artist) {
        setFollowingArtists(user.artist);
      }
    } catch (e) {
      console.warn('Error fetching library data:', e);
    } finally {
      setLoading(false);
    }
  }, [user]);

  const handleCreatePlaylist = async () => {
    if (!newTitle.trim()) return;
    setCreating(true);
    try {
      const res = await playlistApi.createPlaylist(newTitle.trim());
      setNewTitle('');
      setShowCreateModal(false);
      await loadData();
      Alert.alert('Success', res.msg || 'Playlist created!');
    } catch (e) {
      Alert.alert('Error', 'Could not create playlist.');
    } finally {
      setCreating(false);
    }
  };

  const renderPlaylistsView = () => (
    <View style={{ flex: 1 }}>
      {/* Pinned Liked Songs Card */}
      <TouchableOpacity
        style={styles.playlistRow}
        activeOpacity={0.7}
        onPress={() => navigation.navigate('LikedSongs')}
      >
        <LinearGradient colors={['#450af5', '#8e8ee5']} style={styles.likedCover}>
          <Ionicons name="heart" size={24} color="#FFFFFF" />
        </LinearGradient>
        <View style={styles.playlistInfo}>
          <Text style={styles.playlistName}>Liked Songs</Text>
          <Text style={styles.playlistMeta}>Pinned • Playlist</Text>
        </View>
        <Ionicons name="pin" size={16} color={colors.primary} />
      </TouchableOpacity>

      {/* User Created Playlists */}
      <FlatList
        data={playlists}
        keyExtractor={(item, index) => item.name || String(index)}
        contentContainerStyle={{ paddingBottom: 90 }}
        renderItem={({ item }) => (
          <TouchableOpacity
            style={styles.playlistRow}
            activeOpacity={0.7}
            onPress={() =>
              navigation.navigate('PlaylistDetail', {
                playlistId: item.name,
                title: item.name,
                image: item.image,
                isUserPlaylist: true,
              })
            }
          >
            <Image
              source={{
                uri: item.image || 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4',
              }}
              style={styles.playlistCover}
            />
            <View style={styles.playlistInfo}>
              <Text style={styles.playlistName} numberOfLines={1}>
                {item.name}
              </Text>
              <Text style={styles.playlistMeta}>
                Playlist • {item.songs ? `${item.songs.length} songs` : '0 songs'}
              </Text>
            </View>
            <Ionicons name="chevron-forward" size={18} color={colors.textSecondary} />
          </TouchableOpacity>
        )}
      />
    </View>
  );

  const renderRecentlyPlayedView = () => (
    <FlatList
      data={recentSongs}
      keyExtractor={(item, index) => item.songId || String(index)}
      contentContainerStyle={{ paddingBottom: 90 }}
      ListEmptyComponent={
        <Text style={styles.emptyText}>No recently played songs yet.</Text>
      }
      renderItem={({ item, index }) => (
        <SongItem
          song={{
            id: item.songId,
            title: item.songName,
            artist: item.artist,
            image: item.image,
            url: item.songUrl,
            duration: item.len,
          }}
          index={index}
          onPress={() => playSong(item, recentSongs, index)}
        />
      )}
    />
  );

  useEffect(() => {
    loadData();
  }, [loadData]);







  return (
    <SafeAreaView style={styles.safeArea}>
      <View style={styles.container}>
        {/* Top Header */}
        <View style={styles.header}>
          <View style={styles.headerLeft}>
            <TouchableOpacity onPress={() => navigation.navigate('Profile')}>
              <View style={styles.avatar}>
                <Text style={styles.avatarText}>
                  {user?.name ? user.name.charAt(0).toUpperCase() : 'U'}
                </Text>
              </View>
            </TouchableOpacity>
            <Text style={styles.title}>Your Library</Text>
          </View>

          <TouchableOpacity
            style={styles.addBtn}
            onPress={() => setShowCreateModal(true)}
            hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}
          >
            <Ionicons name="add" size={26} color={colors.text} />
          </TouchableOpacity>
        </View>

        {/* Tab Filter Chips */}
        <View style={styles.tabRow}>
          {[
            { id: 'playlists', label: 'Playlists' },
            { id: 'recent', label: 'Recently Played' },
          ].map((tab) => {
            const isActive = activeTab === tab.id;
            return (
              <TouchableOpacity
                key={tab.id}
                style={[styles.tabChip, isActive && styles.tabChipActive]}
                onPress={() => setActiveTab(tab.id)}
              >
                <Text style={[styles.tabText, isActive && styles.tabTextActive]}>
                  {tab.label}
                </Text>
              </TouchableOpacity>
            );
          })}
        </View>

        {/* Tab Body */}
        {loading ? (
          <View style={styles.loadingContainer}>
            <ActivityIndicator size="large" color={colors.primary} />
          </View>
        ) : activeTab === 'playlists' ? (
          renderPlaylistsView()
        ) : (
          renderRecentlyPlayedView()
        )}

        {/* Create Playlist Modal */}
        <Modal visible={showCreateModal} transparent animationType="fade">
          <View style={styles.modalOverlay}>
            <View style={styles.modalBox}>
              <Text style={styles.modalTitle}>Give your playlist a name</Text>
              <TextInput
                style={styles.modalInput}
                placeholder="My Playlist #1"
                placeholderTextColor={colors.textSecondary}
                value={newTitle}
                onChangeText={setNewTitle}
                autoFocus
              />
              <View style={styles.modalRow}>
                <TouchableOpacity
                  style={styles.modalCancel}
                  onPress={() => setShowCreateModal(false)}
                >
                  <Text style={styles.modalCancelText}>Cancel</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={styles.modalSave}
                  onPress={handleCreatePlaylist}
                  disabled={creating}
                >
                  {creating ? (
                    <ActivityIndicator size="small" color="#000" />
                  ) : (
                    <Text style={styles.modalSaveText}>Create</Text>
                  )}
                </TouchableOpacity>
              </View>
            </View>
          </View>
        </Modal>
      </View>
    </SafeAreaView>
  );
};

